import{_ as l,C as a,o as i,c as g,a6 as s,E as e,j as r,a as d}from"./chunks/framework.CrjICMdL.js";const h="/rb_cobot_docs_muscat/images/program/move-jb-form.avif",c="/rb_cobot_docs_muscat/images/program/move-jb-point.avif",_=JSON.parse('{"title":"동작 JB","description":"","frontmatter":{"title":"동작 JB","outline":[2,3]},"headers":[],"relativePath":"manual/program/move-jb.md","filePath":"manual/program/move-jb.md","lastUpdated":1792552919000}'),b={name:"manual/program/move-jb.md"};function m(p,t,x,y,J,u){const n=a("DemoFrame"),o=a("ScenarioSteps");return i(),g("div",null,[t[0]||(t[0]=s('<h1 id="동작-jb" tabindex="-1">동작 JB <a class="header-anchor" href="#동작-jb" aria-label="Permalink to &quot;동작 JB&quot;">​</a></h1><p><strong>동작 JB</strong>는 여러 포인트를 <strong>조인트 공간</strong>에서 <strong>하나의 동작으로 묶어</strong> 실행하는 동작 명령입니다. 포인트마다 정한 <strong>블렌드</strong> 값으로 다음 포인트로 이어 갑니다. 여러 지점을 이어서 지나가는 동작을 한 번에 만들 때 사용합니다.</p><p>이 문서에서는 <strong>프로그램</strong> 화면에서 다음을 해 봅니다.</p><ul><li>동작 JB를 추가하고 포인트 더하기</li><li>포인트 여러 개의 목표 값·블렌드 정하기</li><li>프로그램을 실행해 가상 로봇이 움직이는 것 확인하기</li></ul><div class="warning custom-block"><p class="custom-block-title">안전</p><p>동작 JB는 프로그램을 <strong>실행하면 로봇이 실제로 움직이는</strong> 명령입니다. 실행하기 전에 로봇 주변에 사람이나 장애물이 없는지 확인하고, 포인트와 블렌드 값을 확인합니다. 아래의 실습은 가상 로봇이라 실제 로봇은 움직이지 않습니다.</p></div><h2 id="동작-jb의-구성" tabindex="-1">동작 JB의 구성 <a class="header-anchor" href="#동작-jb의-구성" aria-label="Permalink to &quot;동작 JB의 구성&quot;">​</a></h2><p>동작 JB는 두 종류의 항목으로 이루어집니다.</p><table tabindex="0"><thead><tr><th>항목</th><th>역할</th></tr></thead><tbody><tr><td><strong>동작 JB</strong></td><td>동작의 종류를 정하는 항목입니다. 설정 화면에서 로봇 모델·동작 유형·옵션·메모를 확인합니다.</td></tr><tr><td><strong>포인트</strong></td><td>동작 JB 아래에 놓이는 항목으로, 로봇이 지나갈 위치를 하나씩 담습니다. 동작 JB를 추가하면 <strong>첫 번째 포인트가 함께 만들어지고</strong>, 목표 값은 그때 로봇의 현재 값으로 채워집니다.</td></tr></tbody></table><p>프로그램을 실행하면 동작 JB 아래의 포인트들이 순서대로 모여 하나의 동작으로 실행됩니다. 포인트마다 속도와 블렌드를 따로 정합니다.</p><h2 id="동작-jb-설정-화면" tabindex="-1">동작 JB 설정 화면 <a class="header-anchor" href="#동작-jb-설정-화면" aria-label="Permalink to &quot;동작 JB 설정 화면&quot;">​</a></h2><p>트리의 동작 JB를 누르면 열리는 화면입니다.</p><p><img src="'+h+'" alt="동작 JB 설정 화면"></p><div class="tbl-nowrap-2"><table tabindex="0"><thead><tr><th style="text-align:center;">번호</th><th>항목</th><th>설명</th></tr></thead><tbody><tr><td style="text-align:center;">①</td><td><strong>로봇 모델</strong></td><td>이 동작을 실행할 로봇입니다. 바꿀 수 없습니다.</td></tr><tr><td style="text-align:center;">②</td><td><strong>동작 유형</strong></td><td>동작 J, 동작 L, 동작 JB, 동작 LB, 동작 XB 중에서 고릅니다. 유형을 바꾸면 같은 포인트를 쓰는 다른 동작으로 바뀝니다.</td></tr><tr><td style="text-align:center;">③</td><td><strong>옵션</strong></td><td>동작 LB(Intended·Constant)와 동작 XB(Velocity Blending·Position Blending)에서만 고를 수 있고, 동작 JB에서는 비활성화되어 있습니다.</td></tr><tr><td style="text-align:center;">④</td><td><strong>메모</strong></td><td>참고용 메모를 남깁니다.</td></tr><tr><td style="text-align:center;">⑤</td><td><strong>포인트 추가</strong></td><td>동작 JB 아래에 포인트를 하나 더하고 그 포인트의 설정 화면을 엽니다.</td></tr><tr><td style="text-align:center;">⑥</td><td><strong>닫기</strong></td><td>설정 화면을 닫습니다. 저장하지 않은 변경이 있으면 저장하지 않고 닫을지 묻습니다.</td></tr><tr><td style="text-align:center;">⑦</td><td><strong>저장</strong></td><td>변경한 내용을 적용하고 설정 화면을 닫습니다.</td></tr></tbody></table></div><h2 id="포인트-설정-화면" tabindex="-1">포인트 설정 화면 <a class="header-anchor" href="#포인트-설정-화면" aria-label="Permalink to &quot;포인트 설정 화면&quot;">​</a></h2><p>트리의 포인트를 누르면 열립니다. 아래는 새 포인트를 연 상태이며, 설정 화면이 길어 한 장에 모두 담았습니다.</p><p><img src="'+c+'" alt="포인트 설정 화면"></p><h3 id="포인트와-목표-포인트-1-8" tabindex="-1">포인트와 목표 포인트 (①~⑧) <a class="header-anchor" href="#포인트와-목표-포인트-1-8" aria-label="Permalink to &quot;포인트와 목표 포인트 (①~⑧)&quot;">​</a></h3><div class="tbl-nowrap-2"><table tabindex="0"><thead><tr><th style="text-align:center;">번호</th><th>항목</th><th>설명</th></tr></thead><tbody><tr><td style="text-align:center;">①</td><td><strong>포인트 이름</strong></td><td>포인트의 이름입니다. 영문 대소문자, 숫자, 밑줄(<code>_</code>)만 쓸 수 있고 트리에 이 이름으로 표시됩니다.</td></tr><tr><td style="text-align:center;">②</td><td><strong>메모</strong></td><td>참고용 추가 정보를 입력합니다.</td></tr><tr><td style="text-align:center;">③</td><td><strong>입력 방식</strong></td><td><strong>직접 입력</strong>은 목표 값을 그대로 적습니다. <strong>상대 동작</strong>은 <strong>기준 포인트</strong>를 정해 그 포인트를 기준으로 한 상대 위치를 적습니다. 기준 포인트로는 <code>RB_JOINT_REF</code>·<code>RB_JOINT_ENC</code>·<code>RB_POINT_REF</code>·<code>RB_POINT_ENC</code>와, 앞에서 선언한 포인트 변수를 고를 수 있습니다.</td></tr><tr><td style="text-align:center;">④</td><td><strong>현재값 가져오기</strong></td><td>로봇의 현재 값(조인트 공간에서는 현재 조인트 각도)을 목표 값에 채웁니다.</td></tr><tr><td style="text-align:center;">⑤</td><td><strong>미리보기</strong></td><td>입력한 목표 값을 미리보기 창으로 확인합니다.</td></tr><tr><td style="text-align:center;">⑥</td><td><strong>기준 좌표계</strong></td><td>목표 값의 기준입니다. 조인트 공간, 전역 좌표계, 툴 좌표계, 사용자 좌표계, 목표 좌표계 중에서 고릅니다.</td></tr><tr><td style="text-align:center;">⑦</td><td><strong>이동 단위</strong></td><td>mm/deg, m/rad, inch/deg 중에서 고릅니다.</td></tr><tr><td style="text-align:center;">⑧</td><td><strong>목표 값</strong></td><td>조인트 공간이면 J0~J6의 각도를 입력합니다.</td></tr></tbody></table></div><h3 id="속도·부가-축·블렌드·tcp-9-15" tabindex="-1">속도·부가 축·블렌드·TCP (⑨~⑮) <a class="header-anchor" href="#속도·부가-축·블렌드·tcp-9-15" aria-label="Permalink to &quot;속도·부가 축·블렌드·TCP (⑨~⑮)&quot;">​</a></h3><div class="tbl-nowrap-2"><table tabindex="0"><thead><tr><th style="text-align:center;">번호</th><th>항목</th><th>설명</th></tr></thead><tbody><tr><td style="text-align:center;">⑨</td><td><strong>설정 방법</strong></td><td>속도를 <strong>%기반</strong>(슬라이더로 0~100%)으로 정할지 <strong>절대/물리값</strong>(숫자로 입력)으로 정할지 고릅니다. 절대/물리값의 단위는 동작 JB에서 <strong>deg/s</strong>로 표시됩니다.</td></tr><tr><td style="text-align:center;">⑩</td><td><strong>속도</strong></td><td>이 포인트로 이동하는 속도입니다.</td></tr><tr><td style="text-align:center;">⑪</td><td><strong>가속도</strong></td><td>이 포인트로 이동하는 가속도입니다.</td></tr><tr><td style="text-align:center;">⑫</td><td><strong>부가 축</strong></td><td>켜면 부가 축의 목표 값을 입력하는 영역이 나타나며, 부가 축 값에도 <strong>현재값 가져오기</strong>가 있습니다.</td></tr><tr><td style="text-align:center;">⑬</td><td><strong>블렌드 옵션</strong></td><td><strong>백분율</strong>(%)과 <strong>거리</strong>(mm) 중에서 고릅니다.</td></tr><tr><td style="text-align:center;">⑭</td><td><strong>블렌드율 (%) / 블렌드 거리 (mm)</strong></td><td>블렌드 옵션에 따라 이름과 단위가 바뀝니다(백분율이면 블렌드율(%), 거리이면 블렌드 거리(mm)). 이 포인트에서 다음 포인트로 이어 갈 때 적용하는 값입니다.</td></tr><tr><td style="text-align:center;">⑮</td><td><strong>TCP 툴 좌표계</strong></td><td>이 동작에 쓸 툴을 고릅니다. <strong>기존 선택 유지</strong>는 현재 선택된 툴을 그대로 씁니다.</td></tr></tbody></table></div><h3 id="추가-속성·추가-설정-16-19" tabindex="-1">추가 속성·추가 설정 (⑯~⑲) <a class="header-anchor" href="#추가-속성·추가-설정-16-19" aria-label="Permalink to &quot;추가 속성·추가 설정 (⑯~⑲)&quot;">​</a></h3><div class="tbl-nowrap-2"><table tabindex="0"><thead><tr><th style="text-align:center;">번호</th><th>항목</th><th>설명</th></tr></thead><tbody><tr><td style="text-align:center;">⑯</td><td><strong>속성 추가</strong></td><td>이 포인트에 <strong>속성</strong>을 한 줄씩 더합니다. 줄마다 <strong>타입</strong>(디지털 출력, 아날로그 출력, 용접 전류, 용접 전압, 용접 이송 속도, 위빙 진폭, 위빙 속도), <strong>옵션</strong>(연속 변화·단계별 변화), <strong>포트</strong>, <strong>값</strong>을 정합니다. 디지털 출력은 포트와 Low·High를, 아날로그 출력은 포트와 전압을 정하고, 디지털 출력과 위빙 진폭·속도 타입에서는 옵션을 고를 수 없습니다.</td></tr><tr><td style="text-align:center;">⑰</td><td><strong>후처리 스크립트</strong></td><td>포인트 동작이 완료된 후 실행할 명령을 입력합니다.</td></tr><tr><td style="text-align:center;">⑱</td><td><strong>Finish At 조건</strong></td><td>지정한 조건이 충족되면 모션 명령이 완료되기 전에 동작을 종료합니다.</td></tr><tr><td style="text-align:center;">⑲</td><td><strong>정지 시간 (초)</strong></td><td>Finish At 조건이 충족된 후 동작을 종료하기까지의 시간입니다. 0초를 입력하면 즉시 정지합니다.</td></tr></tbody></table></div><h3 id="화면-위쪽-버튼-20-22" tabindex="-1">화면 위쪽 버튼 (⑳~㉒) <a class="header-anchor" href="#화면-위쪽-버튼-20-22" aria-label="Permalink to &quot;화면 위쪽 버튼 (⑳~㉒)&quot;">​</a></h3><div class="tbl-nowrap-2"><table tabindex="0"><thead><tr><th style="text-align:center;">번호</th><th>항목</th><th>설명</th></tr></thead><tbody><tr><td style="text-align:center;">⑳</td><td><strong>닫기</strong></td><td>설정 화면을 닫습니다.</td></tr><tr><td style="text-align:center;">㉑</td><td><strong>저장</strong></td><td>포인트를 적용하고 설정 화면을 닫습니다.</td></tr><tr><td style="text-align:center;">㉒</td><td><strong>조작 패널(게임패드 아이콘)</strong></td><td>로봇을 움직여 볼 수 있는 조그 창을 엽니다. 로봇을 원하는 자세로 옮긴 뒤 ④ 현재값 가져오기로 그 자세를 포인트에 담을 수 있습니다.</td></tr></tbody></table></div><h2 id="직접-해-보기" tabindex="-1">직접 해 보기 <a class="header-anchor" href="#직접-해-보기" aria-label="Permalink to &quot;직접 해 보기&quot;">​</a></h2><p>동작 JB에 포인트를 여러 개 더해 서로 다른 자세로 정한 뒤, 프로그램을 실행해 가상 로봇이 포인트를 차례로 지나 움직이는 것까지 확인합니다. 프로그램에는 대기(1초)가 먼저 들어 있습니다. 실습은 세 가지이며 어느 쪽부터 해도 되고, 앞의 실습을 하지 않아도 시작할 수 있습니다. 실습을 다시 시작하면 바꾼 값은 처음 상태로 돌아갑니다.</p><h3 id="포인트-설정하기" tabindex="-1">포인트 설정하기 <a class="header-anchor" href="#포인트-설정하기" aria-label="Permalink to &quot;포인트 설정하기&quot;">​</a></h3><p>동작 JB를 추가하고 포인트의 목표 값과 블렌드율을 정하는 과정입니다.</p><ol><li>대기(1초) 아래 빈 영역을 눌러 위치를 정하고 편집 아이콘으로 명령어 목록을 연 뒤 <strong>동작 JB</strong>를 추가합니다. 첫 번째 포인트가 함께 만들어집니다.</li><li>트리에서 동작 JB를 눌러 설정 화면을 열고 구성 영역을 확인합니다.</li><li><strong>포인트 추가</strong>를 눌러 두 번째 포인트를 더하고, 목표 포인트의 <strong>J0</strong>에 <code>45</code>, 블렌드율에 <code>50</code>을 입력한 뒤 저장합니다. 입력한 값이 안내와 같아야 다음으로 넘어갈 수 있으며, 건너뛰면 자동으로 입력됩니다.</li></ol>',29)),e(n,{id:"program-move-jb-point"}),t[1]||(t[1]=r("h4",{id:"사용-방법",tabindex:"-1"},[d("사용 방법 "),r("a",{class:"header-anchor",href:"#사용-방법","aria-label":'Permalink to "사용 방법"'},"​")],-1)),e(o,{id:"program-move-jb-point"}),t[2]||(t[2]=s('<h3 id="여러-포인트-구성하기" tabindex="-1">여러 포인트 구성하기 <a class="header-anchor" href="#여러-포인트-구성하기" aria-label="Permalink to &quot;여러 포인트 구성하기&quot;">​</a></h3><p>포인트가 두 개 있는 동작 JB에 포인트를 더해 네 개로 늘리는 과정입니다.</p><ol><li>트리에서 동작 JB를 눌러 설정 화면을 열고 <strong>포인트 추가</strong>로 세 번째 포인트를 더한 뒤 <strong>J3</strong>에 <code>45</code>를 입력하고 저장합니다.</li><li>같은 방법으로 네 번째 포인트의 <strong>J0</strong>에 <code>-45</code>를 입력하고 저장합니다. 포인트마다 목표 포인트는 로봇의 현재 자세로 채워지므로 입력한 관절만 다른 자세가 됩니다.</li></ol>',3)),e(n,{id:"program-move-jb-points"}),t[3]||(t[3]=r("h4",{id:"사용-방법-1",tabindex:"-1"},[d("사용 방법 "),r("a",{class:"header-anchor",href:"#사용-방법-1","aria-label":'Permalink to "사용 방법"'},"​")],-1)),e(o,{id:"program-move-jb-points"}),t[4]||(t[4]=r("h3",{id:"완성된-경로-실행하기",tabindex:"-1"},[d("완성된 경로 실행하기 "),r("a",{class:"header-anchor",href:"#완성된-경로-실행하기","aria-label":'Permalink to "완성된 경로 실행하기"'},"​")],-1)),t[5]||(t[5]=r("p",null,"포인트가 네 개인 동작 JB를 실행해 가상 로봇이 움직이는 것을 모니터 화면에서 확인하는 과정입니다.",-1)),t[6]||(t[6]=r("ol",null,[r("li",null,"트리 위쪽의 모니터 아이콘으로 모니터 화면을 열고, 재생(▶)을 누릅니다."),r("li",null,"먼저 1초 대기한 뒤 로봇이 J0을 45°까지 돌린 뒤, J3을 접어 올리고, 반대쪽(J0 -45°)으로 넘어가 멈춥니다. 모니터 화면의 3D 화면과 J0~J6 값이 함께 바뀝니다.")],-1)),e(n,{id:"program-move-jb-run"}),t[7]||(t[7]=r("h4",{id:"사용-방법-2",tabindex:"-1"},[d("사용 방법 "),r("a",{class:"header-anchor",href:"#사용-방법-2","aria-label":'Permalink to "사용 방법"'},"​")],-1)),e(o,{id:"program-move-jb-run"})])}const v=l(b,[["render",m]]);export{_ as __pageData,v as default};
